using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Collect all errors
var errors = new List<(string project, string code, string text, string file, int line)>();

build.VisitAllChildren<Error>(error => {
    var project = "";
    var node = error.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    // Error inherits from AbstractDiagnostic which has Text property
    errors.Add((project, error.Code ?? "", error.Text ?? error.ToString(), error.File ?? "", error.LineNumber));
});

Console.WriteLine($"Total errors: {errors.Count}");
Console.WriteLine();

// Group by project
var byProject = errors.GroupBy(e => e.project).OrderBy(g => g.Key);
foreach (var group in byProject) {
    Console.WriteLine($"=== Project: {group.Key} ===");
    foreach (var e in group) {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.text}");
    }
    Console.WriteLine();
}
EOF

