cat > /tmp/binlog-reader/Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Also check for warnings that might be relevant (NU* package warnings)
Console.WriteLine("=== Package/NuGet Warnings ===");
build.VisitAllChildren<Warning>(warning => {
    if (warning.Code != null && (warning.Code.StartsWith("NU") || warning.Code.StartsWith("MSB"))) {
        var project = "";
        var node = warning.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        Console.WriteLine($"  [{warning.Code}] {project}: {warning.Text}");
    }
});

// Check project references / dependencies
Console.WriteLine();
Console.WriteLine("=== Project Structure ===");
build.VisitAllChildren<Project>(project => {
    Console.WriteLine($"  Project: {project.Name} (succeeded={project.Succeeded})");
});

// Check for failed targets
Console.WriteLine();
Console.WriteLine("=== Failed Targets ===");
build.VisitAllChildren<Target>(target => {
    if (!target.Succeeded) {
        var project = "";
        var node = target.Parent;
        while (node != null) {
            if (node is Project p) { project = p.Name; break; }
            node = node.Parent;
        }
        Console.WriteLine($"  Target '{target.Name}' failed in {project}");
    }
});
EOF

