var records = reader.ReadRecords(binlogPath);
foreach (var record in records) {
    if (record.Args is Microsoft.Build.Framework.BuildMessageEventArgs msg) {
        if (msg.Message != null && msg.Message.Contains("Newtonsoft")) {
            Console.WriteLine($"MSG: {msg.Message.Substring(0, Math.Min(300, msg.Message.Length))}");
        }
    }
}

// Also dump the embedded project files
Console.WriteLine();
Console.WriteLine("=== Embedded Content ===");
var build = BinaryLog.ReadBuild(binlogPath);
if (build.SourceFiles != null) {
    Console.WriteLine($"Found {build.SourceFiles.Count} embedded source files");
    foreach (var kv in build.SourceFiles) {
        Console.WriteLine($"\n--- {kv.Key} ---");
        Console.WriteLine(kv.Value);
    }
}
EOF

